/*
 * A089227  Numbers k such that 1 + k*ds(k) is prime, where ds(k) is the sum
 *          of digits of k.
 * https://oeis.org/A089227
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n-th integer k such that 1 + k*ds(k) is prime, where
 *            ds(k) is the sum of decimal digits of k. The sequence is
 *            generated by scanning integers in increasing order and keeping
 *            only those that satisfy the condition
 * Range:     u8 n <= 102, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   digit_sum
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Required utilities */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/digit_sum.h"

/* Miller‑Rabin primality test for 64‑bit integers */
static bool is_prime_u64(unsigned long long n)
{
    if (n < 2) return false;
    /* Small primes */
    static const unsigned long long small[] = {2ull,3ull,5ull,7ull,11ull,13ull,17ull,19ull,23ull,29ull,31ull,37ull};
    for (size_t i = 0; i < sizeof small / sizeof *small; ++i) {
        if (n == small[i]) return true;
        if (n % small[i] == 0) return false;
    }
    /* Deterministic bases for < 2^64 */
    static const unsigned long long bases[] = {2ull, 3ull, 5ull, 7ull, 11ull, 13ull};
    unsigned long long d = n - 1, s = 0;
    while ((d & 1) == 0) { d >>= 1; ++s; }

    for (size_t i = 0; i < sizeof bases / sizeof *bases; ++i) {
        unsigned long long a = bases[i] % n;
        if (a == 0) continue;
        unsigned long long x = 1, power = d;
        unsigned long long base = a, mod = n;
        /* modular exponentiation */
        while (power) {
            if (power & 1) x = (unsigned __int128)x * base % mod;
            base = (unsigned __int128)base * base % mod;
            power >>= 1;
        }
        if (x == 1 || x == n-1) continue;
        bool comp = true;
        for (unsigned long long r = 1; r < s; ++r) {
            x = (unsigned __int128)x * x % mod;
            if (x == n-1) { comp = false; break; }
        }
        if (comp) return false;
    }
    return true;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    /* Static storage for computed terms */
    static seq_t *terms = NULL;
    static size_t terms_len = 0;
    static size_t terms_cap = 0;
    static seq_t next_k = 1;       /* next integer to test */

    if (n == 0) return 0;  /* offset 1: undefined for n < 1 */

    /* Return cached term if already computed */
    if (n <= terms_len)
        return terms[n-1];

    /* Grow storage as needed */
    if (terms == NULL) {
        terms_cap = 16;
        terms = (seq_t*)malloc(terms_cap * sizeof(seq_t));
    }

    /* Generate terms until we have at least n */
    while (terms_len < n) {
        seq_t k = next_k;
        seq_t ds = digit_sum(k);
        unsigned long long cand = 1ull + (unsigned long long)k * (unsigned long long)ds;
        if (is_prime_u64(cand)) {
            if (terms_len == terms_cap) {
                terms_cap *= 2;
                terms = (seq_t*)realloc(terms, terms_cap * sizeof(seq_t));
            }
            terms[terms_len++] = k;
        }
        ++next_k;
    }
    return terms[n-1];
}
